def solve(n: int, d: int) -> int:
    # Use floor division for the base quotient and calculate the remainder
    q, r = divmod(n, d)

    # Calculate the absolute values to handle rounding logic for negative numbers
    abs_n, abs_d = abs(n), abs(d)
    abs_q, abs_r = abs(q), abs(r)

    # Check if the remainder is exactly half the divisor
    # 2 * abs_r >= abs_d handles the "round half away from zero" rule
    if 2 * abs_r >= abs_d:
        if n >= 0:
            return abs_q + 1
        else:
            return -(abs_q + 1)
    else:
        return q

def solve(n: int, d: int) -> int:
    # We want to round n/d to the nearest integer.
    # For positive numbers, n/d + 0.5 rounded down gives the correct result.
    # For negative numbers, n/d - 0.5 rounded up gives the correct result.
    # To handle this:
    # Use floor((2*n + d) / (2*d)) for n >= 0
    # Use ceil((2*n - d) / (2*d)) for n < 0
    if n >= 0:
        return (2 * n + d) // (2 * d)
    else:
        # For negative, integer division // floors, so we adjust
        # to effectively achieve ceiling division.
        return (2 * n - d + 1) // (2 * d)

