def solve(expression: str) -> str:
    def parse_operand(s: str) -> Fraction:
        neg = s.startswith('-')
        if neg:
            s = s[1:]
        if '_' in s:
            w, n_d = s.split('_')
            n, d = map(int, n_d.split('/'))
            val = Fraction(w) + Fraction(n, d)
        elif '/' in s:
            n, d = map(int, s.split('/'))
            val = Fraction(n, d)
        else:
            val = Fraction(int(s))
        return -val if neg else val

    tokens = expression.split()

    # Shunting-yard to handle precedence
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    stack = []

    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token in precedence:
            while stack and precedence[stack[-1]] >= precedence[token]:
                output.append(stack.pop())
            stack.append(token)
        else:
            output.append(parse_operand(token))
        i += 1
    while stack:
        output.append(stack.pop())

    eval_stack = []
    for token in output:
        if isinstance(token, Fraction):
            eval_stack.append(token)
        else:
            b = eval_stack.pop()
            a = eval_stack.pop()
            if token == '+': eval_stack.append(a + b)
            elif token == '-': eval_stack.append(a - b)
            elif token == '*': eval_stack.append(a * b)
            elif token == '/':
                if b == 0: return "undefined"
                eval_stack.append(a / b)

    res = eval_stack[0]
    if res == 0: return "0"

    sign = "-" if res < 0 else ""
    res = abs(res)
    w = res.numerator // res.denominator
    n = res.numerator % res.denominator
    d = res.denominator

    if w == 0:
        return f"{sign}{n}/{d}"
    elif n == 0:
        return f"{sign}{w}"
    else:
        return f"{sign}{w}_{n}/{d}"

